function ensureCSS(){document.querySelectorAll('link[data-lh-shell]').forEach(x=>x.remove());const l=document.createElement('link');l.rel='stylesheet';l.href='assets/site.css?v=20261010-nav-v67';l.dataset.lhShell='1';document.head.appendChild(l);const s=document.createElement('style');s.textContent=`:root{--lh-widget-bottom:20px;--lh-widget-side:20px}.whatsapp-contact{position:fixed!important;left:var(--lh-widget-side)!important;right:auto!important;bottom:var(--lh-widget-bottom)!important;top:auto!important;z-index:2147482998!important;margin:0!important;transform:none!important}.reviews{background:linear-gradient(145deg,#080706,#15110b 60%,#201708)!important;border:1px solid rgba(212,167,62,.72)!important;border-radius:24px!important;padding:26px 28px 22px!important;box-shadow:0 20px 50px rgba(26,18,7,.18)!important}.reviews-title{gap:18px!important}.reviews-title .eyebrow{border-radius:999px!important;padding:8px 13px!important;letter-spacing:.14em!important}.reviews-head h2{font-size:27px!important;letter-spacing:-.015em!important}.reviews-head p{font-size:12px!important;color:#d8cfc0!important;margin-top:6px!important}.review-controls button{width:38px!important;height:38px!important;transition:.2s ease!important}.review-controls button:hover{background:#d4a73e!important;color:#111!important}.review-card{height:168px!important;padding:19px 20px!important;border:1px solid rgba(212,167,62,.42)!important;border-radius:18px!important;background:#fffdf8!important;box-shadow:0 10px 26px rgba(0,0,0,.15)!important}.review-card:hover{transform:translateY(-5px)!important;box-shadow:0 18px 34px rgba(0,0,0,.22)!important}.review-person strong,.review-text,.modal-text{color:#17130e!important}.review-person strong{font-size:14px!important}.review-person small{color:#8a641d!important}.review-text{font-size:15px!important;line-height:1.5!important;font-weight:600!important}.read-cue{color:#8a641d!important}.review-dot.active{background:#f1cf74!important}.review-window{mask-image:linear-gradient(90deg,transparent 0,#000 1.5%,#000 98.5%,transparent 100%);-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 1.5%,#000 98.5%,transparent 100%)}@media(max-width:620px){:root{--lh-widget-bottom:12px;--lh-widget-side:12px}.whatsapp-contact{left:var(--lh-widget-side)!important;bottom:var(--lh-widget-bottom)!important;transform:none!important}.whatsapp-contact small{display:none!important}#tidio-chat,#tidio-chat iframe,#tidio-chat-iframe,.tidio-chat-iframe{right:var(--lh-widget-side)!important;bottom:var(--lh-widget-bottom)!important}.reviews{padding:20px 15px 18px!important;border-radius:18px!important}.reviews-head h2{font-size:21px!important}.review-card{height:160px!important}}`;document.head.appendChild(s)}
function enhanceFeedback(){const track=document.getElementById('reviewTrack');if(!track)return;
const heading=document.querySelector('.reviews-head h2'),subtitle=document.querySelector('.reviews-head p'),badge=document.querySelector('.reviews-title .eyebrow');
if(heading)heading.textContent='What Our Learners Say!';
if(subtitle)subtitle.textContent='Real learner experiences from across our international learning community. Select any card to read the full comment.';
if(badge)badge.textContent='Learner Voices';
const reviews=[
{name:'Li Xinyi',city:'Hong Kong',role:'Learner',lang:'中文',text:'我很喜欢这个老师。老师很耐心，也会鼓励我开口说英语。',translation:'I really like this teacher. She is patient and encourages me to speak English.',dir:'ltr'},
{name:'Wang Zihan',city:'China',role:'Young Learner',lang:'中文',text:'老师善于用道具和例子，引导孩子理解课程，课堂很有互动。',translation:'The teacher uses teaching materials and examples well, guides the child to understand the lesson, and makes the class interactive.',dir:'ltr'},
{name:'Sultan',city:'Riyadh',role:'English Learner',lang:'العربية',text:'واااااو… النطق والشرح والتفاعل ممتاز، والدرس واضح وممتع.',translation:'Wow! The pronunciation, explanations and interaction are excellent. The lesson is clear and enjoyable.',dir:'rtl'},
{name:'Aisha K.',city:'India',role:'A-Level Student',lang:'English',text:'The lessons are well-structured and very supportive. I’ve seen real progress in my understanding and confidence.',translation:'',dir:'ltr'},
{name:'Arielle',city:'Indonesia',role:'IB Student',lang:'English',text:'The explanations are clear and organised. I understand how to approach my IB English and Psychology work with much more confidence now.',translation:'',dir:'ltr'},
{name:'Noura',city:'Kuwait',role:'Learner',lang:'العربية',text:'الشرح منظم وواضح، والمعلمة تتأكد أنني أفهم قبل الانتقال إلى النقطة التالية.',translation:'The explanation is organised and clear, and the teacher makes sure I understand before moving to the next point.',dir:'rtl'},
{name:'Mei Lin',city:'Malaysia',role:'English Learner',lang:'English',text:'I like that the lesson is adjusted to what I need. Difficult points are explained again with examples instead of being rushed.',translation:'',dir:'ltr'},
{name:'Pim',city:'Thailand',role:'English Learner',lang:'English',text:'The classes are friendly but focused. I get useful corrections and enough time to practise speaking during the lesson.',translation:'',dir:'ltr'},
{name:'Dr. Nispa',city:'Afghanistan',role:'Professional Learner',lang:'English',text:'The communication lessons are practical and relevant to professional situations. The feedback helps me express myself more clearly.',translation:'',dir:'ltr'},
{name:'Aisha',city:'Saudi Arabia',role:'Learner',lang:'العربية',text:'أحب طريقة تصحيح الأخطاء بهدوء وشرح السبب، وهذا يساعدني على التحدث بثقة أكبر.',translation:'I like the calm way mistakes are corrected and explained. It helps me speak with greater confidence.',dir:'rtl'}
];
track.innerHTML=reviews.map(r=>`<article class="review-slide" data-name="${r.name}" data-city="${r.city}" data-role="${r.role}" data-lang="${r.lang}" data-text="${r.text.replace(/"/g,'&quot;')}" data-translation="${r.translation.replace(/"/g,'&quot;')}" data-dir="${r.dir}"><div class="review-card"><div class="review-top"><div class="review-person"><strong>${r.name}</strong><small>${r.role} · ${r.city}</small></div><span class="stars">★★★★★</span></div><p class="review-text" dir="${r.dir}">${r.text}</p><span class="read-cue">Click to read ↗</span></div></article>`).join('');
const slides=[...track.querySelectorAll('.review-slide')],dots=document.getElementById('reviewDots'),oldControls=document.querySelector('.review-controls');
if(oldControls){const fresh=oldControls.cloneNode(true);oldControls.replaceWith(fresh);const buttons=fresh.querySelectorAll('button');buttons[0]?.addEventListener('click',()=>go(index-1,true));buttons[1]?.addEventListener('click',()=>go(index+1,true))}
if(dots){dots.innerHTML='';slides.forEach((_,i)=>{const d=document.createElement('button');d.className='review-dot'+(i===0?' active':'');d.type='button';d.setAttribute('aria-label',`Show review ${i+1}`);d.addEventListener('click',()=>go(i,true));dots.appendChild(d)})}
let index=0,timer;function visible(){return innerWidth<=620?1:innerWidth<=900?2:3}
function go(n,restart=false){const max=Math.max(0,slides.length-visible());index=n>max?0:n<0?max:n;const gap=12,w=(track.parentElement.clientWidth-(visible()-1)*gap)/visible();track.style.transform=`translateX(-${index*(w+gap)}px)`;[...(dots?.children||[])].forEach((d,i)=>d.classList.toggle('active',i===index));if(restart)start()}
function start(){clearInterval(timer);timer=setInterval(()=>go(index+1),4800)}
addEventListener('resize',()=>go(Math.min(index,Math.max(0,slides.length-visible()))));
slides.forEach(slide=>slide.addEventListener('click',()=>{const modal=document.getElementById('reviewModal'),meta=document.getElementById('modalMeta'),text=document.getElementById('modalText'),translation=document.getElementById('modalTranslation');if(!modal||!meta||!text)return;meta.textContent=`${slide.dataset.name} · ${slide.dataset.role} · ${slide.dataset.city}`;text.textContent=slide.dataset.text;text.dir=slide.dataset.dir||'ltr';if(translation){translation.textContent=slide.dataset.translation||'';translation.classList.toggle('open',Boolean(slide.dataset.translation))}modal.classList.add('open');modal.setAttribute('aria-hidden','false');clearInterval(timer)}));
go(0);start()}
function uploadMarkup(id,listId,subtitle){return `<div class="lesson-upload-head"><span class="lesson-upload-icon">↥</span><div><strong>Supporting Documents</strong><small>${subtitle}</small></div></div><label class="lesson-upload-control" for="${id}"><span>Choose documents or images</span><input id="${id}" type="file" multiple accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,.webp"><b>Browse</b></label><div class="lesson-upload-meta"><span>PDF, Word, JPG, PNG or WEBP</span><span>Reference material only</span></div><div id="${listId}" class="lesson-file-list" aria-live="polite"></div>`}
function addUploadStyles(){if(document.getElementById('lhUploadStyles'))return;const style=document.createElement('style');style.id='lhUploadStyles';style.textContent=`.lesson-upload-box,.upload-box{margin:2px 0 15px!important;padding:15px 16px!important;border:1px solid #dec58f!important;border-radius:13px!important;background:linear-gradient(135deg,#fffdf8,#fff7e7)!important;box-shadow:0 5px 14px rgba(74,49,10,.04)!important;box-sizing:border-box!important}.lesson-upload-head{display:flex;align-items:center;gap:11px;margin-bottom:12px}.lesson-upload-icon{width:34px;height:34px;flex:0 0 34px;display:grid;place-items:center;border-radius:9px;background:#102f3c;color:#efc35a;font-size:19px;font-weight:900}.lesson-upload-head strong{display:block;color:#1d1710;font:700 14px Georgia,serif}.lesson-upload-head small{display:block;margin-top:2px;color:#6a6052;font:10px/1.4 Arial,sans-serif}.lesson-upload-control{min-height:48px;box-sizing:border-box;display:flex!important;align-items:center;justify-content:space-between;gap:12px;margin:0!important;padding:7px 8px 7px 13px!important;border:1px dashed #cda84f!important;border-radius:10px!important;background:#fff!important;cursor:pointer;font:600 11px Arial,sans-serif!important;color:#554a39!important}.lesson-upload-control input{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;pointer-events:none!important}.lesson-upload-control b{padding:9px 14px;border-radius:8px;background:#102f3c;color:#fff;font-size:10px;letter-spacing:.02em}.lesson-upload-meta{display:flex;justify-content:space-between;gap:12px;margin-top:7px;color:#857660;font:9px/1.35 Arial,sans-serif}.lesson-file-list{display:none;margin-top:9px;padding-top:8px;border-top:1px solid #eadcc0;color:#5f533f;font:10px/1.45 Arial,sans-serif}.lesson-file-list.show{display:block}.lesson-file-list span{display:block;padding:2px 0}.lesson-file-list span:before{content:'✓';margin-right:6px;color:#a87312;font-weight:900}@media(max-width:620px){.lesson-upload-meta{display:block}.lesson-upload-meta span{display:block;margin-top:2px}}`;document.head.appendChild(style)}
function wireUpload(input,list,notes){if(!input||!list)return;input.addEventListener('change',()=>{const files=[...input.files];list.classList.toggle('show',files.length>0);list.innerHTML=files.map(f=>`<span>${f.name}</span>`).join('');if(notes){const clean=notes.value.replace(/\n?Supporting files:.*$/s,'').trim();notes.value=files.length?`${clean}${clean?'\n':''}Supporting files: ${files.map(f=>f.name).join(', ')}`:clean}})}
function enhanceBillingUpload(){const notes=document.getElementById('notes');if(!notes)return;addUploadStyles();if(!document.getElementById('lessonFiles')){const field=notes.closest('.field');if(field){const box=document.createElement('div');box.className='lesson-upload-box';box.innerHTML=uploadMarkup('lessonFiles','lessonFileList','Optional · Add files that help us understand the learner’s requirements.');field.insertAdjacentElement('afterend',box);wireUpload(box.querySelector('#lessonFiles'),box.querySelector('#lessonFileList'),notes)}}const resource=document.getElementById('resourceFiles');if(resource){const box=resource.closest('.upload-box');if(box){box.innerHTML=uploadMarkup('resourceFiles','resourceFileList','Optional · Add files that help us understand the resource requirements.');wireUpload(box.querySelector('#resourceFiles'),box.querySelector('#resourceFileList'),null)}}}
